mapper.select:
SELECT cg.group_id, cg.group_name, cg.group_avatar, cg.owner_id, cg.group_type, cg.is_public, cg.created_at, cg.updated_at, COUNT(gm.user_id) AS member_count, u.username AS owner_name FROM chat_groups cg LEFT JOIN group_members gm ON cg.group_id = gm.group_id JOIN users u ON cg.owner_id = u.user_id
(lower(cg.group_name) LIKE lower(concat('%', #{keyword}, '%')))
GROUP BY cg.group_id, cg.group_name, cg.group_avatar, cg.owner_id, cg.group_type, cg.is_public, cg.created_at, cg.updated_at, u.username ORDER BY cg.created_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE group_members
SET role = #{role}
WHERE group_id = #{groupId} AND user_id = #{userId}
